/* Generated by Trae Work — 杏林大典 Content Bible 图表脚本 */
(function () {
  var style = getComputedStyle(document.documentElement);
  var accent = style.getPropertyValue('--accent').trim();
  var accent2 = style.getPropertyValue('--accent2').trim();
  var ink = style.getPropertyValue('--ink').trim();
  var muted = style.getPropertyValue('--muted').trim();
  var rule = style.getPropertyValue('--rule').trim();

  function init(id) {
    var el = document.getElementById(id);
    if (!el) return null;
    return echarts.init(el);
  }

  /* ============ 图 3-1 各领域知识对象规模对比 ============ */
  var chartDomains = init('chart-domains');
  if (chartDomains) {
    var domains = [
      ['伦理与安全（横切）', 12, 'aux'],
      ['M 骨伤科学', 15, 'aux'],
      ['L 推拿学', 18, 'aux'],
      ['J 中医儿科学', 24, 'aux'],
      ['N 养生与康复', 24, 'aux'],
      ['O 文化与医史', 26, 'aux'],
      ['H 中医外科学', 30, 'aux'],
      ['I 中医妇科学', 30, 'aux'],
      ['P 现代医学基础', 30, 'aux'],
      ['F 温病学', 45, 'clin'],
      ['G 中医内科学', 82, 'clin'],
      ['E 中医经典', 100, 'core'],
      ['A 中医基础理论', 110, 'core'],
      ['K 针灸学', 110, 'core'],
      ['D 方剂学', 132, 'core'],
      ['B 中医诊断学', 127, 'core'],
      ['C 中药学', 187, 'core']
    ];
    chartDomains.setOption({
      color: [accent],
      tooltip: {
        trigger: 'axis',
        axisPointer: { type: 'shadow' },
        formatter: function (p) {
          return p[0].name + '<br/>知识对象：<b>' + p[0].value + '</b>（区间中值）';
        }
      },
      grid: { left: 130, right: 40, top: 10, bottom: 28 },
      xAxis: {
        type: 'value',
        axisLabel: { color: muted, fontSize: 11 },
        splitLine: { lineStyle: { color: rule, type: 'dashed' } }
      },
      yAxis: {
        type: 'category',
        data: domains.map(function (d) { return d[0]; }),
        axisLabel: { color: ink, fontSize: 12 },
        axisLine: { lineStyle: { color: rule } },
        axisTick: { show: false }
      },
      series: [{
        type: 'bar',
        data: domains.map(function (d) {
          return {
            value: d[1],
            itemStyle: {
              color: d[2] === 'core' ? accent : (d[2] === 'clin' ? accent2 : muted),
              opacity: d[2] === 'core' ? 0.92 : (d[2] === 'clin' ? 0.85 : 0.6),
              borderRadius: [0, 4, 4, 0]
            }
          };
        }),
        barWidth: '62%',
        label: {
          show: true,
          position: 'right',
          color: ink,
          fontSize: 11,
          fontWeight: 600
        }
      }]
    });
    window.addEventListener('resize', function () { chartDomains.resize(); });
  }
})();
